import subprocess
def readfa(fn):
    d, cur = {}, None
    for line in open(fn):
        line = line.rstrip('\n')
        if line.startswith('>'):
            cur = line[1:]
            d[cur] = ''
        else:
            d[cur] += line
    return d
prim = readfa('primers.fasta')
tmpl = readfa('sequences.fasta')
def rc(s):
    comp = str.maketrans('ACGTacgt', 'TGCAtgca')
    return s.translate(comp)[::-1]
def tm(s):
    r = subprocess.run(['oligotm','-tp','1','-sc','1','-mv','50','-dv','2','-n','0.8','-d','500', s], capture_output=True, text=True)
    return r.stdout.strip() or r.stderr.strip()
for name in ('input','egfp','flag','snap'):
    for d in ('fwd','rev'):
        p = prim[name+'_'+d]
        anneal = p[11:]
        if d == 'fwd':
            loc = tmpl[name].find(anneal)
        else:
            loc = tmpl[name].find(rc(anneal))
        ok = loc >= 0
        t = tm(anneal if len(anneal) <= 36 else anneal[-36:])
        print(name, d, 'len', len(anneal), 'matches', ok, 'tm', t)
